 for(const choice of plan.choices){if(choice.role&&!policy(s,'hire',choice.role)){Object.assign(s,JSON.parse(before));return{ok:false,reason:'Could not recruit safely. Your shift is unchanged.'}}const id=choice.staffId||s.staff.at(-1).id,result=assignStaff(s,id,roomId);if(!result.ok){Object.assign(s,JSON.parse(before));return result}}
